import {createRequire} from 'node:module';
const require = createRequire('/tmp/pw/node_modules/');
const {chromium} = require('playwright');
const step = process.argv[2];
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1400, height: 700}});
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
// time every rAF callback (that's where chart updates happen)
await page.addInitScript(() => {
  const raf = window.requestAnimationFrame.bind(window);
  window.__frames = [];
  window.requestAnimationFrame = (cb) => raf((t) => { const s = performance.now(); cb(t); window.__frames.push(performance.now() - s); });
});
const t0 = Date.now();
await page.goto(`http://localhost:5179/theme-check.html?step=${step}`);
await page.waitForSelector('.cpu-load-chart canvas');
console.log('time to first chart (incl. 300ms mock latency + history generation):', Date.now() - t0, 'ms');
await page.evaluate(() => { window.__frames = []; });
const box = await page.locator('.u-over').boundingBox();
// hover while streaming
for (let i = 0; i < 40; i++) { await page.mouse.move(box.x + box.width * (0.2 + i / 60), box.y + box.height / 2); await page.waitForTimeout(100); }
const res = await page.evaluate(() => {
  const f = window.__frames.filter((d) => d > 0.5).sort((a, b) => a - b);
  return {updateFrames: f.length, median: f[f.length >> 1]?.toFixed(2), p95: f[Math.floor(f.length * 0.95)]?.toFixed(2), max: f[f.length - 1]?.toFixed(2), latest: window.__latest};
});
console.log(JSON.stringify(res));
console.log('points in chart:', await page.evaluate(() => document.querySelector('.cpu-load-chart__plot') && 'ok'));
console.log('errors', JSON.stringify(errors));
await browser.close();
EOF
